/* One parsed file is kept around: a sheet usually asks the same file several times in a row */
static AmodBlock g_block_file = 0;
static char g_block_file_path[260] = "";
static AmodBlock g_block_store = 0;

static MOD_UNUSED void block_forget_file(void) {
    if (g_block_file != 0 && API->blockExpression != 0) API->blockExpression->Free(SELF, g_block_file);
    g_block_file = 0;
    g_block_file_path[0] = 0;
}

static MOD_UNUSED AmodBlock block_file(const char* path) {
    if (API->blockExpression == 0) return 0;
    if (g_block_file != 0 && strcmp(g_block_file_path, path) == 0) return g_block_file;
    block_forget_file();
    g_block_file = API->blockExpression->ParseFile(SELF, path);
    if (g_block_file != 0) {
        strncpy(g_block_file_path, path, sizeof g_block_file_path - 1);
        g_block_file_path[sizeof g_block_file_path - 1] = 0;
    }
    return g_block_file;
}

/* "images/image" walks down the children; an empty path stays at the root */
static MOD_UNUSED AmodBlock block_walk(AmodBlock root, const char* path) {
    char part[64];
    int at = 0;
    if (root == 0 || API->blockExpression == 0) return 0;
    if (path == 0 || path[0] == 0) return root;

    for (;;) {
        int length = 0;
        while (path[at] != 0 && path[at] != '/' && length < (int)sizeof part - 1) part[length++] = path[at++];
        part[length] = 0;
        if (length > 0) {
            root = API->blockExpression->Child(SELF, root, part);
            if (root == 0) return 0;
        }
        if (path[at] == 0) break;
        ++at;
    }
    return root;
}

static MOD_UNUSED int block_read(AmodBlock block, const char* key, AmodValue* value) {
    if (block == 0 || API->blockExpression == 0) return 0;
    memset(value, 0, sizeof *value);
    return API->blockExpression->GetExpr(SELF, block, key, value);
}

static MOD_UNUSED float block_value_number(const AmodValue* value) {
    if (value->kind == AMOD_VALUE_FLOAT) return value->numbers[0];
    if (value->kind == AMOD_VALUE_STRING && value->text != 0) return (float)atof(value->text);
    return (float)value->integer;
}

static MOD_UNUSED float block_file_number(const char* path, const char* block, const char* key) {
    AmodValue value;
    if (block_read(block_walk(block_file(path), block), key, &value) == 0) return 0.0f;
    return block_value_number(&value);
}

static MOD_UNUSED int block_file_text_is(const char* path, const char* block, const char* key, const char* text) {
    AmodValue value;
    if (block_read(block_walk(block_file(path), block), key, &value) == 0) return 0;
    return value.kind == AMOD_VALUE_STRING && value.text != 0 && strcmp(value.text, text) == 0;
}

static MOD_UNUSED int block_file_has(const char* path, const char* block, const char* key) {
    AmodBlock node = block_walk(block_file(path), block);
    return node != 0 && API->blockExpression->HasExpr(SELF, node, key) != 0;
}

static MOD_UNUSED int block_file_children(const char* path, const char* block) {
    AmodBlock node = block_walk(block_file(path), block);
    return node != 0 ? API->blockExpression->ChildCount(SELF, node) : 0;
}

/* The mod's own tree: a place to keep values by name between rules */
static MOD_UNUSED AmodBlock block_store_node(const char* path, int make) {
    char part[64];
    AmodBlock node;
    int at = 0;
    if (API->blockExpression == 0) return 0;
    if (g_block_store == 0) g_block_store = API->blockExpression->NewTree(SELF, "store");
    node = g_block_store;
    if (node == 0 || path == 0 || path[0] == 0) return node;

    for (;;) {
        int length = 0;
        while (path[at] != 0 && path[at] != '/' && length < (int)sizeof part - 1) part[length++] = path[at++];
        part[length] = 0;
        if (length > 0) {
            AmodBlock next = API->blockExpression->Child(SELF, node, part);
            if (next == 0) {
                if (make == 0) return 0;
                next = API->blockExpression->Child(SELF, node, part);
                if (next == 0) return node;
            }
            node = next;
        }
        if (path[at] == 0) break;
        ++at;
    }
    return node;
}

static MOD_UNUSED void block_store_set_number(const char* path, const char* key, float number) {
    AmodValue value;
    AmodBlock node = block_store_node(path, 1);
    if (node == 0) return;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_FLOAT;
    value.count = 1;
    value.numbers[0] = number;
    API->blockExpression->SetExpr(SELF, node, key, &value);
}

static MOD_UNUSED void block_store_set_text(const char* path, const char* key, const char* text) {
    AmodValue value;
    AmodBlock node = block_store_node(path, 1);
    if (node == 0) return;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_STRING;
    value.text = text;
    API->blockExpression->SetExpr(SELF, node, key, &value);
}

static MOD_UNUSED float block_store_number(const char* path, const char* key) {
    AmodValue value;
    if (block_read(block_store_node(path, 0), key, &value) == 0) return 0.0f;
    return block_value_number(&value);
}

static MOD_UNUSED int block_store_text_is(const char* path, const char* key, const char* text) {
    AmodValue value;
    if (block_read(block_store_node(path, 0), key, &value) == 0) return 0;
    return value.kind == AMOD_VALUE_STRING && value.text != 0 && strcmp(value.text, text) == 0;
}

static MOD_UNUSED int block_store_has(const char* path, const char* key) {
    AmodBlock node = block_store_node(path, 0);
    return node != 0 && API->blockExpression->HasExpr(SELF, node, key) != 0;
}

static MOD_UNUSED void block_store_remove(const char* path, const char* key) {
    AmodBlock node = block_store_node(path, 0);
    if (node != 0) API->blockExpression->RemoveExpr(SELF, node, key);
}

static MOD_UNUSED void block_store_clear(void) {
    if (g_block_store != 0 && API->blockExpression != 0) API->blockExpression->Free(SELF, g_block_store);
    g_block_store = 0;
}

/* A fragment of script text, parsed where it stands. The last one is kept, because a sheet
   usually asks the same text for several keys in a row */
static AmodBlock g_block_text = 0;
static char g_block_text_source[512] = "";

static MOD_UNUSED AmodBlock block_fragment(const char* text) {
    if (API->blockExpression == 0 || text == 0 || text[0] == 0) return 0;
    if (g_block_text != 0 && strcmp(g_block_text_source, text) == 0) return g_block_text;
    if (g_block_text != 0) API->blockExpression->Free(SELF, g_block_text);

    g_block_text = API->blockExpression->Parse(SELF, text);
    if (g_block_text != 0 && strlen(text) < sizeof g_block_text_source) strcpy(g_block_text_source, text);
    else g_block_text_source[0] = 0;
    return g_block_text;
}

static MOD_UNUSED float block_text_number(const char* text, const char* path, const char* key) {
    AmodValue value;
    if (block_read(block_walk(block_fragment(text), path), key, &value) == 0) return 0.0f;
    return block_value_number(&value);
}

static MOD_UNUSED int block_text_has(const char* text, const char* path, const char* key) {
    AmodBlock node = block_walk(block_fragment(text), path);
    return node != 0 && API->blockExpression->HasExpr(SELF, node, key) != 0;
}

/* What a block holds, by number rather than by name: for a sheet that walks it in a loop */
static MOD_UNUSED const char* block_child_name(AmodBlock block, int index) {
    const char* name;
    if (API->blockExpression == 0 || block == 0) return "";
    name = API->blockExpression->Name(SELF, API->blockExpression->ChildAt(SELF, block, index));
    return name != 0 ? name : "";
}

static MOD_UNUSED const char* block_file_child_name(const char* file, const char* path, int index) {
    return block_child_name(block_walk(block_file(file), path), index);
}

static MOD_UNUSED int block_file_keys(const char* file, const char* path) {
    AmodBlock node = block_walk(block_file(file), path);
    return node != 0 ? API->blockExpression->ExprCount(SELF, node) : 0;
}

static MOD_UNUSED const char* block_file_key_name(const char* file, const char* path, int index) {
    AmodBlock node = block_walk(block_file(file), path);
    const char* name = node != 0 ? API->blockExpression->ExprNameAt(SELF, node, index) : 0;
    return name != 0 ? name : "";
}

/* A tree of the mod's own, hung on a game object and found again by the same address.
   Where such an address comes from: the raw pointer of a menu item, for one */
static MOD_UNUSED AmodBlock block_object(uintptr_t object, int make) {
    void* const handle = (void*)object;
    AmodBlock tree;
    if (API->blockExpression == 0 || handle == 0) return 0;
    tree = API->blockExpression->Find(SELF, handle);
    if (tree == 0 && make != 0) tree = API->blockExpression->Attach(SELF, handle);
    return tree;
}

static MOD_UNUSED void block_object_set_number(uintptr_t object, const char* key, float number) {
    AmodValue value;
    AmodBlock tree = block_object(object, 1);
    if (tree == 0) return;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_FLOAT;
    value.count = 1;
    value.numbers[0] = number;
    API->blockExpression->SetExpr(SELF, tree, key, &value);
}

static MOD_UNUSED float block_object_number(uintptr_t object, const char* key) {
    AmodValue value;
    if (block_read(block_object(object, 0), key, &value) == 0) return 0.0f;
    return block_value_number(&value);
}

static MOD_UNUSED int block_object_has(uintptr_t object, const char* key) {
    AmodBlock tree = block_object(object, 0);
    return tree != 0 && (key[0] == 0 || API->blockExpression->HasExpr(SELF, tree, key) != 0);
}

static MOD_UNUSED void block_object_forget(uintptr_t object) {
    if (API->blockExpression != 0 && object != 0) API->blockExpression->Detach(SELF, (void*)object);
}
